import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`site-feasibility-report`,heroTitle:`Build your site feasibility report in minutes`,heroSubtitle:`Perplexity Computer analyzes a property listing, researches zoning and market data, and delivers a complete feasibility report — automatically.`,inputUrlCta:`Analyze this site`,inputUrlPlaceholder:`e.g. property listing URL`,inputUrlPrefill:`Go to {url} and perform a comprehensive site feasibility analysis for commercial real estate development. 1) Extract the property details — address, lot size, current use, asking price, and any listed zoning information. 2) Research the local zoning code, permitted uses, setback requirements, FAR limits, height restrictions, and any overlay districts or special conditions. 3) Pull comparable sales and lease rates for the surrounding submarket within the last 12 months. 4) Analyze demographic and traffic data for the trade area — population density, median household income, daytime population, and average daily traffic counts on adjacent roads. 5) Identify environmental or regulatory red flags — flood zones, wetlands, brownfield history, or historic designations. 6) Estimate a rough development budget range based on site size, zoning capacity, and local construction cost benchmarks. 7) Deliver a structured site feasibility report with a go/no-go recommendation, key risk factors, development potential summary, and next steps for due diligence.`,heroOverlaySteps:[`Extracting property details, lot size, and zoning information`,`Researching local zoning codes, comps, and market data`,`Analyzing demographics, traffic, and environmental risk factors`,`Feasibility report with go/no-go recommendation — ready to review`],generatingSteps:[`Visiting {url} to extract property details, zoning, and site specifications`,`Designing an agent to research zoning codes, comps, demographics, and environmental risk`,`Configuring development potential modeling and construction cost benchmarking`,`Setting up your feasibility report with risk scoring and due diligence next steps`],featureSectionTitle:`From listing to feasibility report`,featureCardTitles:[`Connects to your CRE stack`,`Outputs you can underwrite`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Airtable, Slack — Computer pipes your feasibility data and reports into the tools your deal team already uses.`,`Zoning summaries. Comparable sales and lease comps. Demographic profiles. Environmental risk flags. Development budget estimates. A go/no-go recommendation with next steps.`],capabilitySectionTitle:`Your site analyst, on autopilot`,capabilitySectionSubtitle:`Paste a listing, step away, come back to a complete feasibility report.`,capabilityCards:[{title:`Zoning Analysis`,description:`Computer can research permitted uses, FAR limits, height restrictions, setbacks, and overlay districts — and flag any entitlement risks before you spend on due diligence.`},{title:`Market Comps`,description:`Computer can pull comparable sales and lease rates for the submarket — giving you a clear read on pricing, absorption, and competitive supply.`},{title:`Demographic Research`,description:`Computer can analyze trade area demographics — population density, household income, daytime traffic, and growth trends — to validate demand assumptions.`},{title:`Connect Your Tools`,description:`Computer can push reports and data into Google Sheets, Google Drive, Airtable, Notion, and Slack — keeping your deal pipeline and team in sync.`},{title:`Remember & Learn`,description:`Computer can remember your investment criteria, preferred markets, and past deal screens — so every new feasibility analysis matches your underwriting standards.`},{title:`Monitor & Alert`,description:`Computer can track zoning changes, new listings, and market shifts for sites in your pipeline — and flag updates that affect your feasibility assumptions.`}]});export{t as default};
